}

:root {
  color-scheme: dark;
  --bg: #070809;
  --panel: rgba(13, 14, 15, 0.82);
  --panel-deep: rgba(8, 9, 10, 0.9);
  --line: rgba(236, 231, 221, 0.13);
  --line-soft: rgba(236, 231, 221, 0.075);
  --text: #f0ece3;
  --dim: #8d8a82;
  --dim-2: #6d6a63;
  --gold: #cba35f;
  --gold-bright: #e8c98c;
  --gold-soft: rgba(203, 163, 95, 0.14);
  --green: #81a382;
  --radius: 16px;
  --ui-pad: 24px;
  --top-offset: 96px;
  --sans: 'Manrope', 'Avenir Next', 'Helvetica Neue', sans-serif;
  --serif: 'Instrument Serif', 'Iowan Old Style', 'Baskerville', Georgia, serif;
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: var(--bg);
}

body {
  color: var(--text);
  font-family: var(--sans);
  font-size: 13px;
  letter-spacing: 0.01em;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
}

button,
input,
select {
  font: inherit;
}

button {
  color: inherit;
}

button:focus-visible,
a:focus-visible {
  outline: 1px solid var(--gold-bright);
  outline-offset: 3px;
}

button {
  -webkit-tap-highlight-color: transparent;
}

.app {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 100dvh;
  isolation: isolate;
  background:
    radial-gradient(ellipse at 55% 42%, rgba(73, 66, 55, 0.16), transparent 48%),
    radial-gradient(ellipse at 64% 18%, rgba(155, 131, 90, 0.082), transparent 39%),
    radial-gradient(ellipse at 26% 74%, rgba(66, 79, 77, 0.08), transparent 45%),
    linear-gradient(155deg, #0c0d0e 0%, #070809 42%, #050606 100%);
}

.backdrop {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}

.backdrop-glow {
  position: absolute;
  width: 56vw;
  height: 56vw;
  left: 47%;
  top: 42%;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(196, 159, 98, 0.075), transparent 65%);
  filter: blur(30px);
}

.backdrop-grid {
  position: absolute;
  inset: 0;
  opacity: 0.25;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.018) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.018) 1px, transparent 1px);
  background-size: 76px 76px;
  mask-image: radial-gradient(ellipse at 50% 48%, black 0%, transparent 74%);
  -webkit-mask-image: radial-gradient(ellipse at 50% 48%, black 0%, transparent 74%);
}

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  outline: none;
}

.vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 52% 48%, transparent 44%, rgba(0, 0, 0, 0.28) 78%, rgba(0, 0, 0, 0.6) 100%),
    linear-gradient(180deg, rgba(0, 0, 0, 0.23), transparent 17% 77%, rgba(0, 0, 0, 0.34));
  z-index: 2;
}

.grain {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  opacity: 0.032;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  background-size: 240px 240px;
  mix-blend-mode: soft-light;
}

.ui {
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
}

.hud-bar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 10;
  height: 82px;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 20px;
  padding: 14px var(--ui-pad);
  pointer-events: none;
}

.brand {
  justify-self: start;
  display: flex;
  align-items: center;
  gap: 13px;
  min-width: 0;
  color: var(--text);
  text-decoration: none;
  pointer-events: auto;
}

.brand-mark {
  width: 32px;
  height: 38px;
  color: var(--gold);
  display: grid;
  place-items: center;
  border-right: 1px solid rgba(203, 163, 95, 0.3);
  padding-right: 13px;
  flex: 0 0 auto;
}

.brand-mark svg {
  width: 29px;
  height: 29px;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.brand-title {
  font-family: var(--sans);
  font-weight: 600;
  font-size: 15px;
  line-height: 1;
  letter-spacing: 0.2em;
  white-space: nowrap;
}

.brand-title i {
  font-style: normal;
  color: var(--gold);
  padding: 0 1px;
}

.brand-sub {
  color: var(--dim);
  font-size: 7.5px;
  line-height: 1;
  letter-spacing: 0.25em;
  font-weight: 600;
  white-space: nowrap;
}

.view-switch {
  justify-self: center;
  display: flex;
  gap: 2px;
  padding: 3px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: rgba(9, 10, 11, 0.64);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.18), inset 0 1px 0 rgba(255, 255, 255, 0.035);
  backdrop-filter: blur(18px) saturate(115%);
  -webkit-backdrop-filter: blur(18px) saturate(115%);
  pointer-events: auto;
}

.view-btn {
  height: 31px;
  padding: 0 14px;
  display: flex;
  align-items: center;
  gap: 8px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--dim);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.17em;
  cursor: pointer;
  transition: color 180ms ease, background 180ms ease, box-shadow 180ms ease;
}

.view-btn svg {
  width: 14px;
  height: 14px;
}

.view-btn:hover {
  color: var(--text);
}

.view-btn.is-active {
  color: var(--gold-bright);
  background: linear-gradient(180deg, rgba(203, 163, 95, 0.16), rgba(203, 163, 95, 0.07));
  box-shadow: inset 0 0 0 1px rgba(203, 163, 95, 0.17);
}

.top-status {
  justify-self: end;
  display: flex;
  align-items: center;
  gap: 15px;
  pointer-events: none;
}

.system-state {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #b5b0a5;
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.15em;
  white-space: nowrap;
}

.live-pip,
.mini-pip {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 0 3px rgba(129, 163, 130, 0.1), 0 0 12px rgba(129, 163, 130, 0.4);
  animation: breathe 2.8s ease-in-out infinite;
}

.clock {
  font-variant-numeric: tabular-nums;
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.15em;
  color: var(--dim);
  min-width: 66px;
  text-align: right;
  padding-right: 1px;
}

.icon-btn {
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  color: var(--dim);
  background: rgba(8, 9, 10, 0.4);
  cursor: pointer;
  pointer-events: auto;
  transition: color 180ms ease, border-color 180ms ease, background 180ms ease;
}

.icon-btn svg {
  width: 16px;
  height: 16px;
}

.icon-btn:hover {
  color: var(--text);
  border-color: rgba(203, 163, 95, 0.36);
  background: rgba(203, 163, 95, 0.08);
}

/* Panels */
.panel {
  position: relative;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    linear-gradient(145deg, rgba(22, 23, 24, 0.76), rgba(8, 9, 10, 0.86)),
    var(--panel);
  box-shadow:
    0 22px 60px rgba(0, 0, 0, 0.28),
    inset 0 1px 0 rgba(255, 255, 255, 0.036);
  backdrop-filter: blur(24px) saturate(118%);
  -webkit-backdrop-filter: blur(24px) saturate(118%);
  pointer-events: auto;
}

.panel::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background: linear-gradient(105deg, rgba(255, 255, 255, 0.025), transparent 32%, transparent 70%, rgba(203, 163, 95, 0.028));
}

.panel-kicker {
  display: block;
  color: var(--dim);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.23em;
  line-height: 1.2;
  text-transform: uppercase;
}

.left-rail {
  position: absolute;
  top: var(--top-offset);
  left: var(--ui-pad);
  bottom: 24px;
  width: 306px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  pointer-events: none;
  z-index: 8;
}

.agent-panel {
  padding: 19px 20px 16px;
  overflow: hidden;
  transition: opacity 220ms ease, transform 220ms ease;
}

.agent-panel.is-hidden {
  display: none;
}

.agent-panel::after {
  content: '';
  position: absolute;
  top: 0;
  left: 20px;
  width: 28px;
  height: 1px;
  background: var(--gold);
  opacity: 0.75;
}

.panel-topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 18px;
  margin-bottom: 14px;
}

.panel-close {
  width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: var(--dim-2);
  cursor: pointer;
  transition: color 180ms ease, background 180ms ease;
}

.panel-close:hover {
  color: var(--text);
  background: rgba(255, 255, 255, 0.05);
}

.panel-close svg {
  width: 13px;
  height: 13px;
}

.agent-identity {
  display: flex;
  align-items: center;
  gap: 13px;
}

.monogram {
  width: 47px;
  height: 52px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  position: relative;
  border: 1px solid rgba(203, 163, 95, 0.25);
  border-radius: 7px;
  background: linear-gradient(145deg, rgba(203, 163, 95, 0.11), rgba(255, 255, 255, 0.012));
  color: var(--gold-bright);
  font-family: var(--serif);
  font-size: 26px;
  line-height: 1;
}

.monogram::after {
  content: '';
  position: absolute;
  width: 5px;
  height: 5px;
  right: 6px;
  top: 6px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 8px rgba(129, 163, 130, 0.7);
}

.agent-name {
  margin: 0;
  font-family: var(--serif);
  font-size: 36px;
  line-height: 0.92;
  font-weight: 400;
  letter-spacing: -0.012em;
  color: #f4f0e8;
}

.agent-role {
  margin: 6px 0 0;
  color: var(--gold);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.17em;
  line-height: 1.3;
  text-transform: uppercase;
}

.agent-status-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 16px 0 14px;
  padding-bottom: 13px;
  border-bottom: 1px solid var(--line-soft);
}

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #d8d2c5;
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.status-pill .status-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 10px rgba(203, 163, 95, 0.5);
}

.status-pill.is-active .status-dot {
  animation: breathe 2.4s ease-in-out infinite;
}

.status-meta {
  margin-left: auto;
  color: var(--dim-2);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.15em;
}

.task-label {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  color: var(--dim);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.2em;
}

.task-label span:last-child {
  color: var(--dim-2);
  letter-spacing: 0.12em;
}

.current-task {
  margin: 7px 0 12px;
  min-height: 34px;
  font-family: var(--serif);
  font-size: 19px;
  line-height: 1.15;
  color: #e9e4da;
  letter-spacing: 0.005em;
}

.progress-meta {
  display: flex;
  justify-content: space-between;
  color: var(--dim-2);
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.14em;
  margin-bottom: 6px;
}

.progress-meta strong {
  color: var(--gold);
  font-weight: 600;
}

.progress-track {
  height: 2px;
  position: relative;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.075);
}

.progress-fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: 0%;
  background: linear-gradient(90deg, #9d7c46, var(--gold-bright));
  box-shadow: 0 0 10px rgba(203, 163, 95, 0.34);
  transition: width 400ms linear;
}

.progress-fill::after {
  content: '';
  position: absolute;
  top: 0;
  right: 0;
  width: 12px;
  height: 100%;
  background: rgba(255, 241, 214, 0.6);
  filter: blur(3px);
}

.directives {
  margin-top: 14px;
}

.directive-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 5px;
  margin-top: 7px;
}

.directive-btn {
  min-height: 29px;
  border: 1px solid var(--line-soft);
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.018);
  color: #aaa69d;
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.14em;
  cursor: pointer;
  transition: border-color 160ms ease, color 160ms ease, background 160ms ease;
}

.directive-btn:hover {
  color: var(--gold-bright);
  border-color: rgba(203, 163, 95, 0.35);
  background: rgba(203, 163, 95, 0.08);
}

.agent-metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  margin: 16px 0 14px;
  padding: 11px 0;
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
  background:
    linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.03) 49.8%, transparent 50.2%, transparent 99.8%, rgba(255, 255, 255, 0.03) 100%);
}

.agent-metric {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding-left: 10px;
}

.agent-metric:first-child {
  padding-left: 0;
}

.agent-metric span {
  color: var(--dim-2);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.16em;
}

.agent-metric b {
  color: #dcd6ca;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.02em;
}

.focus-btn {
  width: 100%;
  height: 35px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 12px;
  border: 1px solid rgba(203, 163, 95, 0.28);
  border-radius: 5px;
  background: linear-gradient(90deg, rgba(203, 163, 95, 0.1), rgba(203, 163, 95, 0.03));
  color: var(--gold-bright);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.17em;
  cursor: pointer;
  transition: background 180ms ease, border-color 180ms ease;
}

.focus-btn svg {
  width: 15px;
  height: 15px;
}

.focus-btn:hover {
  background: rgba(203, 163, 95, 0.16);
  border-color: rgba(203, 163, 95, 0.5);
}

.agent-footnote {
  display: flex;
  justify-content: space-between;
  margin-top: 11px;
  color: var(--dim-2);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.14em;
}

.agent-footnote span:last-child {
  color: var(--gold);
  opacity: 0.75;
}

/* Executive console */
.console-panel {
  padding: 19px 20px 16px;
}

.console-panel.is-hidden {
  display: none;
}

.console-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.console-title {
  margin: 7px 0 3px;
  font-family: var(--serif);
  font-size: 31px;
  line-height: 1;
  font-weight: 400;
}

.console-title i {
  color: var(--gold);
  font-style: normal;
}

.console-sub {
  margin: 0;
  color: var(--dim);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.console-rule {
  width: 100%;
  height: 1px;
  margin: 15px 0;
  background: var(--line-soft);
}

.console-metrics {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  background: var(--line-soft);
  border: 1px solid var(--line-soft);
}

.console-metric {
  padding: 10px 10px 9px;
  background: rgba(10, 11, 12, 0.7);
}

.console-metric span {
  display: block;
  color: var(--dim-2);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.15em;
  margin-bottom: 4px;
}

.console-metric b {
  color: #e6e0d4;
  font-family: var(--serif);
  font-size: 22px;
  font-weight: 400;
}

.console-metric small {
  color: var(--gold);
  font-family: var(--sans);
  font-size: 7px;
  letter-spacing: 0.12em;
  margin-left: 3px;
}

.console-actions {
  display: grid;
  gap: 6px;
  margin-top: 14px;
}

.console-action {
  width: 100%;
  height: 34px;
  border: 1px solid var(--line-soft);
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.018);
  color: #c7c1b6;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 11px;
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.14em;
  cursor: pointer;
  transition: background 180ms ease, border-color 180ms ease, color 180ms ease;
}

.console-action svg {
  width: 14px;
  height: 14px;
  opacity: 0.65;
}

.console-action:hover {
  color: var(--gold-bright);
  border-color: rgba(203, 163, 95, 0.34);
  background: rgba(203, 163, 95, 0.075);
}

.console-action.is-primary {
  border-color: rgba(203, 163, 95, 0.33);
  background: linear-gradient(90deg, rgba(203, 163, 95, 0.14), rgba(203, 163, 95, 0.04));
  color: var(--gold-bright);
}

.console-note {
  margin: 13px 0 0;
  color: var(--dim-2);
  font-size: 8px;
  line-height: 1.55;
  letter-spacing: 0.04em;
}

/* Camera dock */
.camera-dock {
  margin-top: auto;
  padding: 12px 13px 11px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(9, 10, 11, 0.66);
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.18), inset 0 1px 0 rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  pointer-events: auto;
}

.camera-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--dim);
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.2em;
  margin-bottom: 9px;
}

.camera-mode {
  color: var(--gold);
  letter-spacing: 0.12em;
  opacity: 0.8;
}

.camera-actions {
  display: flex;
  gap: 4px;
}

.dock-btn {
  height: 30px;
  width: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid var(--line-soft);
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.018);
  color: var(--dim);
  cursor: pointer;
  transition: color 160ms ease, background 160ms ease, border-color 160ms ease;
}

.dock-btn svg {
  width: 13px;
  height: 13px;
}

.dock-btn--wide {
  margin-left: auto;
  width: 82px;
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.14em;
}

.dock-btn:hover {
  color: var(--gold-bright);
  border-color: rgba(203, 163, 95, 0.3);
  background: rgba(203, 163, 95, 0.075);
}

.camera-hint {
  margin: 9px 0 0;
  color: var(--dim-2);
  font-size: 6.8px;
  font-weight: 600;
  letter-spacing: 0.1em;
  line-height: 1.5;
}

.hint-touch {
  display: none;
}

/* Right rail */
.right-rail {
  position: absolute;
  top: var(--top-offset);
  right: var(--ui-pad);
  bottom: 24px;
  width: 316px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  pointer-events: none;
  z-index: 8;
}

.roster-panel,
.feed-panel {
  padding: 17px 18px 0;
  overflow: hidden;
}

.roster-panel {
  flex: 0 0 auto;
}

.panel-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 11px;
}

.panel-heading h2 {
  margin: 4px 0 0;
  font-family: var(--serif);
  font-size: 24px;
  line-height: 1;
  font-weight: 400;
  letter-spacing: 0.005em;
}

.count-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 5px 7px;
  border: 1px solid var(--line-soft);
  border-radius: 4px;
  color: var(--dim-2);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.12em;
  white-space: nowrap;
}

.count-chip b {
  color: var(--gold-bright);
  font-weight: 500;
}

.roster-list {
  display: flex;
  flex-direction: column;
}

.roster-item {
  position: relative;
  width: 100%;
  min-height: 52px;
  display: grid;
  grid-template-columns: 26px 34px 1fr auto;
  align-items: center;
  gap: 9px;
  padding: 7px 5px 7px 0;
  border: 0;
  border-top: 1px solid var(--line-soft);
  background: transparent;
  text-align: left;
  cursor: pointer;
  transition: background 160ms ease;
}

.roster-item:last-child {
  border-bottom: 1px solid var(--line-soft);
}

.roster-item::before {
  content: '';
  position: absolute;
  left: -18px;
  top: 50%;
  width: 2px;
  height: 0;
  background: var(--gold);
  transform: translateY(-50%);
  transition: height 180ms ease;
}

.roster-item:hover {
  background: rgba(255, 255, 255, 0.022);
}

.roster-item.is-active {
  background: linear-gradient(90deg, rgba(203, 163, 95, 0.075), transparent 76%);
}

.roster-item.is-active::before {
  height: 24px;
}

.roster-index {
  color: var(--dim-2);
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.13em;
}

.roster-avatar {
  width: 30px;
  height: 32px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 5px;
  color: #bfb8aa;
  background: rgba(255, 255, 255, 0.022);
  font-family: var(--serif);
  font-size: 16px;
  line-height: 1;
  transition: border-color 160ms ease, color 160ms ease;
}

.roster-item.is-active .roster-avatar {
  color: var(--gold-bright);
  border-color: rgba(203, 163, 95, 0.35);
  background: rgba(203, 163, 95, 0.08);
}

.roster-copy {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.roster-name {
  color: #ded9ce;
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  white-space: nowrap;
}

.roster-role {
  color: var(--dim-2);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.roster-side {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
  max-width: 85px;
}

.roster-status {
  display: flex;
  align-items: center;
  gap: 5px;
  color: #88847a;
  font-size: 6.5px;
  font-weight: 600;
  letter-spacing: 0.1em;
  white-space: nowrap;
  text-transform: uppercase;
}

.roster-status i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--gold);
  opacity: 0.82;
}

.roster-item.is-active .roster-status {
  color: var(--gold-bright);
}

.roster-progress {
  width: 48px;
  height: 1px;
  background: rgba(255, 255, 255, 0.06);
  overflow: hidden;
}

.roster-progress span {
  display: block;
  height: 100%;
  width: 0;
  background: rgba(203, 163, 95, 0.65);
  transition: width 400ms linear;
}

.roster-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 31px;
  color: var(--dim-2);
  font-size: 6.5px;
  font-weight: 600;
  letter-spacing: 0.1em;
}

.roster-footer span {
  display: flex;
  align-items: center;
  gap: 6px;
}

.roster-footer .mini-pip {
  width: 4px;
  height: 4px;
}

/* Feed */
.feed-panel {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-height: 220px;
  padding-bottom: 0;
}

.feed-heading {
  margin-bottom: 7px;
}

.live-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--gold);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.14em;
  margin-top: 2px;
}

.live-chip i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 8px rgba(203, 163, 95, 0.6);
  animation: breathe 2.2s ease-in-out infinite;
}

.feed-list {
  position: relative;
  flex: 1;
  overflow: hidden auto;
  padding: 3px 0 7px;
  scrollbar-width: thin;
  scrollbar-color: rgba(203, 163, 95, 0.25) transparent;
}

.feed-list::-webkit-scrollbar {
  width: 3px;
}

.feed-list::-webkit-scrollbar-thumb {
  background: rgba(203, 163, 95, 0.24);
}

.feed-item {
  position: relative;
  display: grid;
  grid-template-columns: 39px 1fr;
  gap: 8px;
  padding: 8px 0 8px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
  animation: feed-in 320ms ease both;
}

.feed-item:last-child {
  border-bottom: 0;
}

.feed-time {
  display: flex;
  flex-direction: column;
  gap: 3px;
  align-items: flex-start;
  color: var(--dim-2);
  font-size: 6.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
  font-variant-numeric: tabular-nums;
  padding-top: 1px;
}

.feed-time::after {
  content: '';
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: rgba(203, 163, 95, 0.45);
}

.feed-copy {
  min-width: 0;
}

.feed-copy p {
  margin: 0;
  color: #c4beb2;
  font-size: 9px;
  line-height: 1.5;
  letter-spacing: 0.015em;
}

.feed-copy p b {
  color: #e7e1d6;
  font-weight: 600;
}

.feed-copy small {
  display: block;
  margin-top: 3px;
  color: var(--dim-2);
  font-size: 6.5px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.feed-item.is-accent .feed-copy p {
  color: #d5c5a8;
}

.feed-item.is-accent .feed-time::after {
  background: var(--gold);
  box-shadow: 0 0 7px rgba(203, 163, 95, 0.55);
}

.feed-item.is-fresh .feed-time::after {
  background: var(--green);
  box-shadow: 0 0 7px rgba(129, 163, 130, 0.55);
}

.feed-item.is-muted .feed-copy p {
  color: var(--dim);
}

.feed-footer {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  align-items: center;
  min-height: 30px;
  margin: 0 -18px;
  padding: 0 18px;
  border-top: 1px solid var(--line-soft);
  color: var(--dim-2);
  font-size: 6.2px;
  font-weight: 600;
  letter-spacing: 0.1em;
  background: rgba(0, 0, 0, 0.1);
}

.feed-age {
  color: rgba(129, 163, 130, 0.75);
}

/* Operations */
.operations-bar {
  position: absolute;
  left: 50%;
  bottom: 23px;
  transform: translateX(-50%);
  height: 49px;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: rgba(10, 11, 12, 0.82);
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.32), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  backdrop-filter: blur(24px) saturate(120%);
  -webkit-backdrop-filter: blur(24px) saturate(120%);
  pointer-events: auto;
  z-index: 9;
}

.ops-btn {
  height: 39px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 0 13px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: #a29d92;
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.15em;
  cursor: pointer;
  transition: background 160ms ease, color 160ms ease;
}

.ops-btn:hover {
  color: var(--text);
  background: rgba(255, 255, 255, 0.045);
}

.ops-icon {
  width: 16px;
  height: 16px;
  display: grid;
  place-items: center;
}

.ops-icon svg {
  width: 15px;
  height: 15px;
}

.speed-btn {
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  gap: 0;
  min-width: 45px;
  padding: 0 8px;
}

.speed-value {
  color: var(--gold-bright);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.03em;
}

.speed-caption {
  color: var(--dim-2);
  font-size: 6px;
  letter-spacing: 0.15em;
  margin-top: 2px;
}

.ops-divider {
  width: 1px;
  height: 22px;
  background: var(--line-soft);
  margin: 0 3px;
}

.standup-btn {
  position: relative;
  height: 39px;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 0 14px;
  border: 1px solid rgba(203, 163, 95, 0.34);
  border-radius: 5px;
  background: linear-gradient(180deg, rgba(203, 163, 95, 0.2), rgba(203, 163, 95, 0.085));
  color: #eedbb8;
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.14em;
  cursor: pointer;
  transition: border-color 180ms ease, background 180ms ease;
  overflow: hidden;
}

.standup-btn:hover {
  border-color: rgba(232, 201, 140, 0.62);
  background: linear-gradient(180deg, rgba(203, 163, 95, 0.28), rgba(203, 163, 95, 0.12));
}

.standup-btn svg {
  width: 15px;
  height: 15px;
  opacity: 0.76;
}

.standup-btn.is-active {
  border-color: rgba(232, 201, 140, 0.52);
  background: rgba(203, 163, 95, 0.19);
}

.standup-btn.is-active .standup-pulse {
  background: var(--gold-bright);
  animation: breathe 1.4s ease-in-out infinite;
}

.standup-pulse {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 9px rgba(203, 163, 95, 0.5);
}

.standup-btn:disabled {
  opacity: 0.4;
  cursor: default;
  filter: grayscale(0.5);
}

.floor-marker {
  position: absolute;
  left: 50%;
  bottom: 82px;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  color: rgba(194, 187, 175, 0.34);
  font-size: 6px;
  font-weight: 600;
  letter-spacing: 0.2em;
  white-space: nowrap;
  pointer-events: none;
}

.floor-line {
  display: block;
  width: 22px;
  height: 1px;
  background: rgba(194, 187, 175, 0.16);
}

/* Hover tooltip */
.hover-tooltip {
  position: fixed;
  left: 0;
  top: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 9px 8px 10px;
  border: 1px solid rgba(203, 163, 95, 0.23);
  border-radius: 7px;
  background: rgba(8, 9, 10, 0.9);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(15px);
  -webkit-backdrop-filter: blur(15px);
  pointer-events: none;
  opacity: 0;
  transform: translate(-50%, calc(-100% - 15px)) scale(0.98);
  transition: opacity 110ms ease, transform 110ms ease;
  z-index: 20;
}

.hover-tooltip.is-visible {
  opacity: 1;
  transform: translate(-50%, calc(-100% - 15px)) scale(1);
}

.tooltip-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 8px rgba(203, 163, 95, 0.65);
}

.tooltip-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tooltip-copy b {
  color: #eae3d5;
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.15em;
}

.tooltip-copy small {
  color: var(--dim);
  font-size: 6px;
  font-weight: 600;
  letter-spacing: 0.13em;
}

.tooltip-key {
  display: grid;
  place-items: center;
  width: 19px;
  height: 19px;
  margin-left: 2px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: var(--dim-2);
  font-size: 8px;
}

/* Floating tag */
.agent-tag {
  position: fixed;
  left: 0;
  top: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  transform: translate(-50%, -100%);
  transition: opacity 160ms ease;
  pointer-events: none;
  z-index: 7;
}

.agent-tag.is-hidden {
  opacity: 0;
}

.tag-line {
  width: 1px;
  height: 27px;
  background: linear-gradient(180deg, rgba(203, 163, 95, 0), rgba(203, 163, 95, 0.6));
}

.tag-copy {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 5px 8px;
  border: 1px solid rgba(203, 163, 95, 0.22);
  border-radius: 4px;
  background: rgba(7, 8, 9, 0.85);
  backdrop-filter: blur(10px);
}

.tag-copy b {
  color: #ebe4d4;
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.15em;
}

.tag-copy small {
  color: var(--gold);
  font-size: 5.5px;
  font-weight: 600;
  letter-spacing: 0.13em;
}

/* Toast */
.toast-region {
  position: absolute;
  top: 94px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  pointer-events: none;
  z-index: 30;
}

.toast {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: rgba(11, 12, 13, 0.88);
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.25);
  backdrop-filter: blur(18px);
  color: #d3ccbf;
  font-size: 8px;
  font-weight: 500;
  letter-spacing: 0.06em;
  animation: toast-in 260ms ease both;
}

.toast::before {
  content: '';
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 8px rgba(203, 163, 95, 0.55);
}

.toast.is-leaving {
  animation: toast-out 240ms ease both;
}

/* Help dialog */
.help-dialog {
  width: min(690px, calc(100vw - 32px));
  max-height: calc(100dvh - 40px);
  overflow: auto;
  padding: 27px 28px 20px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background:
    linear-gradient(150deg, rgba(25, 26, 27, 0.96), rgba(7, 8, 9, 0.98));
  color: var(--text);
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.65), inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.help-dialog::backdrop {
  background: rgba(3, 4, 5, 0.66);
  backdrop-filter: blur(8px);
}

.help-dialog[open] {
  animation: dialog-in 260ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.dialog-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.help-dialog h2 {
  margin: 20px 0 10px;
  font-family: var(--serif);
  font-size: clamp(34px, 5vw, 49px);
  line-height: 1;
  font-weight: 400;
  letter-spacing: -0.01em;
}

.help-dialog h2 em {
  color: var(--gold-bright);
  font-style: normal;
}

.dialog-lede {
  max-width: 510px;
  margin: 0;
  color: #a8a297;
  font-size: 11px;
  line-height: 1.7;
  letter-spacing: 0.01em;
}

.dialog-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
  margin-top: 25px;
  padding-top: 20px;
  border-top: 1px solid var(--line-soft);
}

.shortcut-list {
  margin: 10px 0 0;
}

.shortcut-list div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 5px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.035);
}

.shortcut-list dt {
  color: #d2cbbf;
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.02em;
}

.shortcut-list dd {
  margin: 0;
  color: var(--dim-2);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-align: right;
}

kbd {
  display: inline-block;
  min-width: 16px;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: #b8b2a6;
  font-family: var(--sans);
  font-size: 7px;
  line-height: 1;
  text-align: center;
}

.dialog-note {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  margin-top: 20px;
  padding: 13px 14px;
  border: 1px solid rgba(203, 163, 95, 0.18);
  border-radius: 7px;
  background: rgba(203, 163, 95, 0.055);
}

.note-mark {
  color: var(--gold);
  font-family: var(--serif);
  font-size: 21px;
  line-height: 1;
}

.dialog-note p {
  margin: 0;
  color: #b7b0a3;
  font-size: 9px;
  line-height: 1.6;
}

.dialog-note b {
  color: #e7dfcf;
  font-weight: 600;
}

.dialog-footer {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  margin-top: 22px;
  padding-top: 13px;
  border-top: 1px solid var(--line-soft);
  color: var(--dim-2);
  font-size: 6.5px;
  font-weight: 600;
  letter-spacing: 0.12em;
}

/* Boot */
.boot-screen {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  background:
    radial-gradient(ellipse at 50% 46%, rgba(82, 72, 55, 0.16), transparent 52%),
    #060708;
  transition: opacity 650ms cubic-bezier(0.4, 0, 0.2, 1), visibility 650ms;
}

.boot-screen.is-complete {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.boot-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 250px;
}

.boot-mark {
  color: var(--gold);
  width: 54px;
  height: 54px;
  margin-bottom: 15px;
  animation: boot-float 4s ease-in-out infinite;
}

.boot-mark svg {
  width: 100%;
  height: 100%;
}

.boot-title {
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.26em;
  color: #eee8dc;
}

.boot-title i {
  color: var(--gold);
  font-style: normal;
}

.boot-sub {
  margin-top: 6px;
  color: var(--dim-2);
  font-size: 6.5px;
  font-weight: 600;
  letter-spacing: 0.27em;
}

.boot-track {
  width: 100%;
  height: 1px;
  margin-top: 33px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.boot-track span {
  display: block;
  width: 12%;
  height: 100%;
  background: linear-gradient(90deg, rgba(203, 163, 95, 0), var(--gold-bright));
  transition: width 300ms ease;
}

.boot-meta {
  width: 100%;
  display: flex;
  justify-content: space-between;
  margin-top: 9px;
  color: var(--dim-2);
  font-size: 6px;
  font-weight: 600;
  letter-spacing: 0.16em;
}

/* Animations */
@keyframes breathe {
  0%, 100% { opacity: 0.55; transform: scale(0.88); }
  50% { opacity: 1; transform: scale(1.08); }
}

@keyframes feed-in {
  from { opacity: 0; transform: translateY(-5px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes toast-in {
  from { opacity: 0; transform: translateY(-5px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes toast-out {
  from { opacity: 1; transform: translateY(0); }
  to { opacity: 0; transform: translateY(-4px); }
}

@keyframes dialog-in {
  from { opacity: 0; transform: translateY(9px) scale(0.99); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes boot-float {
  0%, 100% { transform: translateY(0); opacity: 0.8; }
  50% { transform: translateY(-5px); opacity: 1; }
}

