page.on('pageerror', e => console.log('PAGEERROR', e.message))
await page.goto('http://127.0.0.1:5173', { waitUntil: 'networkidle' })
await page.waitForFunction(() => window.__AGENT_HQ_READY__ === true, null, { timeout: 60000 })
