  a: { p: [17.6, 15.6, 20.4], t: [0, 0.62, -0.25] },
  b: { p: [17.6, 16.4, 21.0], t: [1.55, 0.6, -0.7] },
  c: { p: [18.4, 17.4, 22.6], t: [2.5, 0.6, -1.0] },
