  g: { p: [18.0, 28.0, 18.0], t: [1.0, 0.2, -1.2] },
}

for (const [name, c] of Object.entries(candidates)) {
  await page.evaluate(({ p, t }) => {
    const hq = window.AGENT_HQ
    hq.camera.position.set(...p)
    hq.controls.target.set(...t)
