import { createRequire } from 'node:module'
import { join } from 'node:path'
import { readFileSync } from 'node:fs'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true, timeout: 30000 })
for (const [name, width, height, mobile] of [['tablet', 1180, 820, false], ['mobile', 390, 844, true]]) {
  const page = await browser.newPage({ viewport: { width, height }, isMobile: mobile, hasTouch: mobile })
  await page.goto('http://127.0.0.1:5173', { waitUntil: 'networkidle' })
  await page.waitForFunction(() => window.__AGENT_HQ_READY__ === true, null, { timeout: 60000 })
  await page.waitForTimeout(1000)
  await page.evaluate(() => window.AGENT_HQ.setView('top', { animate: false }))
  await page.waitForTimeout(700)
  await page.screenshot({ path: `/tmp/viewports/${name}-top.png` })
  await page.close()
}
await browser.close()

import { createRequire } from 'node:module'
import { join } from 'node:path'
import { readFileSync } from 'node:fs'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const errors = []
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message) })
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE ERROR', m.text()) })
await page.goto('http://127.0.0.1:5173', { waitUntil: 'networkidle' })
await page.waitForFunction(() => window.__AGENT_HQ_READY__ === true, null, { timeout: 60000 })
await page.waitForTimeout(1200)

const results = []
function check(name, cond, detail = '') {
  results.push({ name, ok: Boolean(cond), detail })
  console.log(cond ? 'PASS' : 'FAIL', name, detail)
}
async function state() { return page.evaluate(() => window.AGENT_HQ.getState()) }
async function resetView() {
  await page.evaluate(() => window.AGENT_HQ.resetCamera())
  await page.waitForTimeout(1200)
}
async function elementAt(x, y) {
  return page.evaluate(({ x, y }) => document.elementFromPoint(x, y)?.id || document.elementFromPoint(x, y)?.className || 'unknown', { x, y })
}

check('roster has five agents', await page.locator('.roster-item').count() === 5)
check('Nova selected by default', (await page.locator('#agent-panel .agent-name').textContent()) === 'Nova')

// Click an agent in the canvas.
let projected = await page.evaluate(() => window.AGENT_HQ.projectAgent('echo'))
console.log('echo projected', projected, 'element', await elementAt(projected.x, projected.y))
await page.mouse.click(projected.x, projected.y)
await page.waitForTimeout(450)
check('canvas agent click selects Echo', (await page.locator('#agent-panel .agent-name').textContent()) === 'Echo')

// Roster click.
await page.locator('.roster-item[data-agent-id="atlas"]').click()
await page.waitForTimeout(300)
check('roster selects Atlas', (await page.locator('#agent-panel .agent-name').textContent()) === 'Atlas')

// Keyboard 3 selects Iris.
await page.keyboard.press('3')
await page.waitForTimeout(250)
check('keyboard 3 selects Iris', (await page.locator('#agent-panel .agent-name').textContent()) === 'Iris')

// Directive.
await page.locator('[data-directive="analyze"]').click()
await page.waitForTimeout(300)
check('directive updates task', (await page.locator('.current-task').textContent()).includes('Deep analysis'), await page.locator('.current-task').textContent())

// Top view button.
await page.locator('[data-view="top"]').click()
await page.waitForTimeout(1300)
check('top view active', await page.locator('[data-view="top"]').getAttribute('aria-pressed') === 'true')
await page.locator('[data-view="iso"]').click()
await page.waitForTimeout(1300)
check('iso view active', await page.locator('[data-view="iso"]').getAttribute('aria-pressed') === 'true')

// Drag rotates camera.
const beforeRotate = await page.evaluate(() => window.AGENT_HQ.camera.position.toArray())
await page.mouse.move(760, 430)
await page.mouse.down()
await page.mouse.move(860, 470, { steps: 8 })
await page.mouse.up()
await page.waitForTimeout(500)
const afterRotate = await page.evaluate(() => window.AGENT_HQ.camera.position.toArray())
check('drag rotates camera', JSON.stringify(beforeRotate) !== JSON.stringify(afterRotate))
check('drag sets free orbit label', (await page.locator('#camera-mode').textContent()) === 'FREE ORBIT')

// Wheel zoom.
const beforeZoom = await page.evaluate(() => window.AGENT_HQ.camera.position.distanceTo(window.AGENT_HQ.controls.target))
await page.mouse.move(760, 430)
await page.mouse.wheel(0, -400)
await page.waitForTimeout(500)
const afterZoom = await page.evaluate(() => window.AGENT_HQ.camera.position.distanceTo(window.AGENT_HQ.controls.target))
check('wheel zooms camera', Math.abs(beforeZoom - afterZoom) > 0.2, `${beforeZoom.toFixed(2)} -> ${afterZoom.toFixed(2)}`)

// Reset camera and click the boardroom table.
await resetView()
let boardPoint = await page.evaluate(() => window.AGENT_HQ.projectWorld(7.9, 0.9, -4.16))
console.log('board point', boardPoint, 'element', await elementAt(boardPoint.x, boardPoint.y))
await page.mouse.click(boardPoint.x, boardPoint.y)
await page.waitForTimeout(500)
let st = await state()
check('canvas boardroom click starts stand-up', st.meeting?.phase === 'gather', JSON.stringify(st.meeting))
check('stand-up locks button', await page.locator('#standup-btn').isDisabled())
const duringMeetingPos = await page.evaluate(() => window.AGENT_HQ.camera.position.toArray())
await page.waitForTimeout(1300)
const afterFocusPos = await page.evaluate(() => window.AGENT_HQ.camera.position.toArray())
check('stand-up focuses boardroom', JSON.stringify(duringMeetingPos) !== JSON.stringify(afterFocusPos), `${duringMeetingPos.map(n => n.toFixed(1))} -> ${afterFocusPos.map(n => n.toFixed(1))}`)

// Deterministically advance the simulation to complete the stand-up.
await page.evaluate(() => {
  const hq = window.AGENT_HQ
  const sim = hq.simulation
  const guard = 1200
  for (let i = 0; i < guard && sim.meeting; i += 1) sim.update(0.05)
  hq.ui.tick()
})
await page.waitForTimeout(700)
st = await state()
check('stand-up completes and agents return', st.meeting === null && st.agents.every(a => a.mode === 'desk'), st.agents.map(a => a.mode).join(','))
check('stand-up button re-enabled', !(await page.locator('#standup-btn').isDisabled()))

// Executive console via canvas.
await resetView()
const execPoint = await page.evaluate(() => window.AGENT_HQ.projectWorld(-2.45, 0.8, -0.1))
console.log('exec point', execPoint, 'element', await elementAt(execPoint.x, execPoint.y))
await page.mouse.click(execPoint.x, execPoint.y)
await page.waitForTimeout(400)
check('canvas executive click opens console', await page.locator('#console-panel').isVisible())

// Coffee bar via canvas.
await page.evaluate(() => window.AGENT_HQ.clearSelection())
await page.waitForTimeout(200)
const coffeePoint = await page.evaluate(() => window.AGENT_HQ.projectWorld(-10.83, 0.9, 3.16))
console.log('coffee point', coffeePoint, 'element', await elementAt(coffeePoint.x, coffeePoint.y))
await page.mouse.click(coffeePoint.x, coffeePoint.y)
await page.waitForTimeout(400)
const coffeeToast = await page.locator('.toast').last().textContent()
check('canvas coffee click pours a cup', coffeeToast.includes('recharging at The Brief'), coffeeToast)

// Pause + speed.
await page.locator('#pause-btn').click()
await page.waitForTimeout(300)
check('pause toggles', (await state()).paused === true)
const frozen = await page.evaluate(() => window.AGENT_HQ.simulation.elapsed)
await page.waitForTimeout(800)
check('pause freezes simulation time', (await page.evaluate(() => window.AGENT_HQ.simulation.elapsed)) === frozen)
await page.locator('#pause-btn').click()
await page.locator('#speed-btn').click()
await page.waitForTimeout(250)
check('speed toggles to 2x', (await state()).speed === 2)
await page.locator('#speed-btn').click()

// Help dialog.
await page.locator('#help-open').click()
await page.waitForTimeout(300)
check('help dialog opens', await page.locator('#help-dialog').evaluate(d => d.open))
await page.locator('#help-close').click()
await page.waitForTimeout(250)
check('help dialog closes', !(await page.locator('#help-dialog').evaluate(d => d.open)))

// Escape clears selection.
await page.locator('.roster-item[data-agent-id="onyx"]').click()
await page.waitForTimeout(200)
await page.keyboard.press('Escape')
await page.waitForTimeout(200)
check('Escape clears selection', !(await page.locator('#agent-panel').isVisible()))

const metrics = await page.evaluate(() => window.AGENT_HQ.getMetrics())
check('draw calls under 400', metrics.drawCalls < 400, String(metrics.drawCalls))
check('triangles under 250k', metrics.triangles < 250000, String(metrics.triangles))
check('no runtime errors', errors.length === 0, errors.join(' | '))

console.log('\nSUMMARY', results.filter(r => r.ok).length + '/' + results.length, 'passed')
if (results.some(r => !r.ok)) process.exitCode = 1
await browser.close()

