import { createRequire } from 'node:module'
import { join } from 'node:path'
import { readFileSync } from 'node:fs'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true, timeout: 30000 })
const context = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 })
const page = await context.newPage()
const errors = []
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message) })
await page.goto('http://127.0.0.1:5173', { waitUntil: 'networkidle' })
await page.waitForFunction(() => window.__AGENT_HQ_READY__ === true, null, { timeout: 60000 })
await page.waitForTimeout(1200)

const check = (label, ok, info = '') => console.log(ok ? 'PASS' : 'FAIL', label, info)

check('starts with no agent panel', !(await page.locator('#agent-panel').isVisible()))
check('all five roster items present', (await page.locator('.roster-item').count()) === 5)

const nova = await page.evaluate(() => window.AGENT_HQ.projectAgent('nova'))
await page.touchscreen.tap(nova.x, nova.y)
await page.waitForTimeout(500)
check('tap agent opens panel', await page.locator('#agent-panel').isVisible())
check('tap agent selects Nova', (await page.locator('#agent-panel .agent-name').textContent()) === 'Nova')
console.log('panel rect', JSON.stringify(await page.locator('#agent-panel').boundingBox()))
await page.screenshot({ path: '/tmp/viewports/mobile-agent-panel.png' })

await page.locator('#agent-panel .panel-close').tap()
await page.waitForTimeout(300)
check('close button hides panel', !(await page.locator('#agent-panel').isVisible()))

// Touch drag to orbit.
const before = await page.evaluate(() => window.AGENT_HQ.camera.position.toArray())
const client = await page.context().newCDPSession(page)
await client.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: 200, y: 400 }] })
for (let i = 1; i <= 8; i++) {
  await client.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: 200 + i * 8, y: 400 + i * 2 }] })
}
await client.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] })
await page.waitForTimeout(700)
const after = await page.evaluate(() => window.AGENT_HQ.camera.position.toArray())
check('touch drag orbits camera', JSON.stringify(before) !== JSON.stringify(after), `${before.map(n => n.toFixed(2))} -> ${after.map(n => n.toFixed(2))}`)

// Touch pinch to zoom.
const distBefore = await page.evaluate(() => window.AGENT_HQ.camera.position.distanceTo(window.AGENT_HQ.controls.target))
await client.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: 170, y: 420, id: 1 }, { x: 230, y: 420, id: 2 }] })
for (let i = 1; i <= 8; i++) {
  await client.send('Input.dispatchTouchEvent', {
    type: 'touchMove',
    touchPoints: [{ x: 170 - i * 5, y: 420, id: 1 }, { x: 230 + i * 5, y: 420, id: 2 }],
  })
}
await client.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] })
await page.waitForTimeout(900)
const distAfter = await page.evaluate(() => window.AGENT_HQ.camera.position.distanceTo(window.AGENT_HQ.controls.target))
check('pinch zoom changes distance', Math.abs(distAfter - distBefore) > 0.5, `${distBefore.toFixed(2)} -> ${distAfter.toFixed(2)}`)

// View toggle and stand-up from mobile controls.
await page.locator('#view-top').tap()
await page.waitForTimeout(1300)
check('top view selected on mobile', (await page.locator('#view-top').getAttribute('class')).includes('is-active'))
await page.evaluate(() => window.AGENT_HQ.setView('iso'))
await page.waitForTimeout(1200)
await page.locator('#standup-btn').tap()
await page.waitForTimeout(500)
const st = await page.evaluate(() => window.AGENT_HQ.getState())
check('mobile stand-up convened', st.meeting?.phase === 'gather', JSON.stringify(st.meeting))
await page.waitForTimeout(1200)
await page.screenshot({ path: '/tmp/viewports/mobile-standup-focus.png' })

check('no runtime errors', errors.length === 0)
console.log('SUMMARY errors', errors.length)
await browser.close()

